/** 按命题顺序分组，丢弃空桶，页面直接遍历渲染 */
function buildGroups(list: Question[]): QuestionGroup[] {
  return QUESTION_CATEGORIES
    .map(category => ({
      category,
      label: CATEGORY_LABELS[category],
      questions: list.filter(q => q.category === category),
    }))
    .filter(group => group.questions.length > 0)
}

export const questionGroups: QuestionGroup[] = buildGroups(questions)
export const totalQuestions = questions.length
